"""
CLI to generate the CIVIS synthetic dataset.

Determinism: given the same seed, this must produce byte-identical output.
The seed is versioned in .env / CI config, not hardcoded in the CLI.

Usage:
    python -m civis.synth.generate --seed 42 --output data/generated/base_v1.json
"""

import argparse
import json
from pathlib import Path

from faker import Faker

from civis.synth.registry_providers import FictionalCivilRegistryProvider

# Number of fictional citizens generated by the v1 base.
# Small on purpose: v1 is a smoke-scale dataset for FSM contract testing,
# not the adversarial battery (which lands in week 5).
DEFAULT_CITIZEN_COUNT = 20

FAKER_LOCALE = "pt_BR"
DEFAULT_OUTPUT_PATH = Path("data/generated/base_v1.json")


def build_faker(seed: int) -> Faker:
    """Build a seeded Faker with the fictional civil-registry provider attached."""
    fake = Faker(FAKER_LOCALE)
    fake.add_provider(FictionalCivilRegistryProvider)
    Faker.seed(seed)
    return fake


def generate_citizen(fake: Faker) -> dict:
    """Generate one fictional citizen record."""
    return {
        "name": fake.name(),
        "cpf": fake.fictional_cpf(),
        "rg": fake.fictional_rg(),
        "birth_certificate_id": fake.fictional_birth_certificate_id(),
        "birth_date": fake.fictional_civil_event_date().isoformat(),
        "address": fake.address(),
    }


def generate_base(seed: int, count: int) -> list[dict]:
    """Generate the v1 synthetic base as a list of citizen records."""
    fake = build_faker(seed)
    return [generate_citizen(fake) for _ in range(count)]


def main() -> None:
    parser = argparse.ArgumentParser(description="Generate CIVIS synthetic base v1.")
    parser.add_argument("--seed", type=int, required=True, help="Random seed (versioned).")
    parser.add_argument(
        "--count",
        type=int,
        default=DEFAULT_CITIZEN_COUNT,
        help=f"Number of citizens to generate (default: {DEFAULT_CITIZEN_COUNT}).",
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=DEFAULT_OUTPUT_PATH,
        help=f"Output JSON file (default: {DEFAULT_OUTPUT_PATH}).",
    )
    args = parser.parse_args()

    base = generate_base(seed=args.seed, count=args.count)

    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(base, indent=2, ensure_ascii=False), encoding="utf-8")

    print(f"Generated {len(base)} fictional citizens -> {args.output}")


if __name__ == "__main__":
    main()
